vl.updateFields()

if gtype == "LineString":
    vl.renderer().symbol().setWidth(1.2)

if len(objList) == 0:
    QgsMessageLog.logMessage("No results found!",
                             level=Qgis.Info)
else:

    if out_path == None:
        QgsMessageLog.logMessage("No data will be added to the map document.", level=Qgis.Info)
    else:
        vl.startEditing()
        for item in objList:
            wkt_literal = item[-1]
            wkt = wkt_literal.replace("<http://www.opengis.net/def/crs/OGC/1.3/CRS84>", "")

            feat = QgsFeature()
            geom = QgsGeometry.fromWkt(wkt)

            feat.setGeometry(geom)

            # check if we need to discard this polygon
            matchFound = False
            for layer in QgsProject.instance().mapLayers().values():
                if layer.name() == input_Layer:
                    ft = layer.getFeatures()
                    for f in ft:
                        geom_poly = f.geometry()

                        if gtype == "Point":
                            if geom_poly.contains(geom):
                                matchFound = True

                        if gtype == "LineString":
                            if geom_poly.intersects(geom):
                                matchFound = True

                        if gtype == "Polygon":
                            if geom_poly.intersects(geom):
                                matchFound = True

            if not matchFound:
                continue

            feat.setAttributes(item[0:-1])

            vl.addFeature(feat)
        vl.endEditCommand()
        vl.commitChanges()
        vl.updateExtents()

        options = QgsVectorFileWriter.SaveVectorOptions()
        options.layerName = "%s_%s_%s"%(layerName, subtype, gtype)
        context = QgsProject.instance().transformContext()
        error = QgsVectorFileWriter.writeAsVectorFormatV2(vl, out_path, context, options)

